Q: How can I queue calls to an async function and execute them in order? A: <p>You can run them as <code>locked</code>.</p>
<pre class="lang-dart prettyprint-override"><code>import 'dart:async';

import 'package:multitasking/synchronization/binary_semaphore.dart';
import 'package:multitasking/synchronization/lock.dart';

int i = 0;

final _lock = BinarySemaphore();

Future&lt;T&gt; runLocked&lt;T&gt;(Lock lock, FutureOr&lt;T&gt; Function() f) async {
  // Wait for any previous calls
  await lock.acquire();
  try {
    return await f();
  } finally {
    await lock.release();
  }
}

Future&lt;int&gt; func(int x) async {
  return runLocked(_lock, () async {
    print('$x $i');
    // Simulate a lengthy operation, such as a network request
    await Future&lt;void&gt;.delayed(Duration(milliseconds: 500));
    print('$x $i');
    i += 1;
    return i;
  });
}

void main() async {
  await func(0);
  func(1);
  func(2);
  // Scheduled and will be called after the next `func(3)`
  Timer(Duration(milliseconds: 800), () =&gt; func(4));
  await func(3);
  func(5);
  await func(6);
  await func(7);
  func(8);
  func(9);
  // Scheduled and will be called after the next `func(10)`
  Timer(Duration(milliseconds: 1), () =&gt; func(11));
  func(10);
}
</code></pre>
